/**
 * Unit tests for TreeTraversingParser.getIntValue().
 * Since TreeTraversingParser is designed to traverse a JsonNode, 
 * we test the behavior based on the state of the underlying node.
 */
public class TreeTraversingParser_getIntValue_TriageGen2Test {

    private ObjectMapper mapper;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
    }





    @Test(expected = ClassCastException.class)
    public void testGetIntValue_ThrowsClassCastException_WhenNotNumeric() throws IOException {
        // Arrange: Create a non-numeric node (TextNode)
        // The method implementation casts currentNumericNode() to (NumericNode)
        // If currentNumericNode() returns a non-numeric node, it should throw ClassCastException
        TextNode textNode = mapper.getNodeFactory().textNode("not a number");
        TreeTraversingParser parser = new TreeTraversingParser(textNode);

        // Act
        parser.getIntValue();

        // Assert: Handled by expected exception
    }




}

