    @Before
    public void setUp() {
        mapper = new ObjectMapper();
    }









    @Test(expected = JsonParseException.class)
    public void testGetIntValue_ThrowsJsonParseException() throws IOException {
        // This test simulates a scenario where currentNumericNode() might throw a JsonParseException
        // based on the method signature provided in the prompt.

        // We use a custom implementation or a node that triggers the internal error logic
        // Since we cannot easily mock the protected method without PowerMock, 
        // we assume the parser behavior for an invalid state.

        // For the sake of coverage of the throws clause:
        // If the underlying node structure is corrupted or empty in a way that currentNumericNode() fails.
        // We simulate this by using a parser that is in an invalid state.
        TreeTraversingParser parser = new TreeTraversingParser(mapper.getNodeFactory().objectNode());

        // In a real Jackson scenario, if the current token is not a number, 
        // currentNumericNode() would likely throw a JsonParseException.
        parser.getIntValue();
    }
